class SpyFoo : public Foo {
 public:
  explicit SpyFoo(Foo& real) : real_(real) {
    ON_CALL(*this, DoThis).WillByDefault(
        [this](int n) { return real_.DoThis(n); });  // delegate to real
  }
  MOCK_METHOD(int, DoThis, (int n), (override));
 private:
  Foo& real_;
};
SpyFoo spy(real);
EXPECT_CALL(spy, DoThis(5)).Times(1);    // record the interaction
use(spy);                                // real code runs
